const form = $('On form submission').first().json;
const company = (form["nom d'entreprise"] || "").trim();
const pays = (form["pays"] || "").trim();

const countryMap = { 'france': 'France', 'belgique': 'Belgium' };
const country = countryMap[pays.toLowerCase()] || pays;

if (company !== "") {
  return [{ json: { type: "company", value: company, country }}];
}

try {
  const translatedKeywords = $('Basic LLM Chain').first().json.text.trim();
  if (translatedKeywords !== "") {
    return [{ json: { type: "keywords", value: translatedKeywords, country }}];
  }
} catch (e) {}

throw new Error("Veuillez entrer un nom d'entreprise ou des mots-clés.");

