// Apollo renvoie un tableau sous $json.organizations
const orgs = $json.organizations || [];

// On récupère tous les primary_domain non-nuls
let domains = orgs
  .map(o => o.primary_domain)          // récupérer le domaine
  .filter(d => d && d.trim() !== "")   // supprimer les null / vides
  .map(d => d.toLowerCase().trim());   // normalisation

// On supprime les doublons
domains = [...new Set(domains)];

// On renvoie un item par domaine pour Split In Batches
return domains.map(domain => ({
  json: { domain }
}));

return items.map(item => {
  const p = item.json.person || {};

  return {
    json: {
      id: p.id,
      firstName: p.first_name,
      lastName: p.last_name,
      title: p.title,
      description:p.organization?.short_description|| "",

      // Email pro
      workEmail: p.email || "",

      // Entreprise
      company: p.organization?.name || "",
      companyDomain: p.organization?.primary_domain || "",

      // LinkedIn
      linkedin: p.linkedin_url || "",
      companyLinkedin: p.organization?.linkedin_url || ""
    }
  };
});

let page = 1;

try {
  const previousItems = $items("Code in JavaScript10");
  if (previousItems.length > 0) {
    page = previousItems[previousItems.length - 1].json.page || 1;
  }
} catch (e) {
  page = 1;
}

const results = [];

for (const item of items) {
  const people = item.json.people || [];

  if (people.length === 0) {
    // 🔴 S'il n'y a personne → on retourne juste la page
    results.push({
      json: {
        page: page
      }
    });
  } else {
    for (const p of people) {
      results.push({
        json: {
          page: page,
          id: p.id,
          first_name: p.first_name,
          last_name: p.last_name,
          title: p.title,
          company: p.organization?.name || ""
        }
      });
    }
  }
}

return results;

